/**
 * OKF projections — the AT-REST navigation façade over `wiki/` (volet ② of
 * Roland's 2026-07-30 decision, vault note
 * `wiki/obsidian-mcp-router/decisions/catalog-journal-et-projections-okf.md`).
 *
 * Three kinds of GENERATED files live inside `wiki/` (= the OKF bundle root):
 *
 *   wiki/index.md          — root index, frontmatter `okf_version` ONLY (§11)
 *   wiki/<dir>/index.md    — one navigation index per content directory (§6)
 *   wiki/log.md            — newest-first content history (§7)
 *
 * They are PROJECTIONS: pure functions of the tree's frontmatter (`title`,
 * `description`, `type`, dates) — never hand-edited, never wikilinked
 * (internal links keep targeting `[[catalog]]`/`[[journal]]`), regenerated by
 * tool/middleware and checked for drift by wiki-lint. Volet ① freed the
 * basenames these files use: Obsidian resolves wikilinks by basename, so
 * before the `index`→`catalog` / `log`→`journal` rename these files would
 * have silently captured ~480 `[[index]]`/`[[log]]` citations.
 *
 * Grammar: identical to the export bundle's, by construction — the §6 index
 * builder IS the exporter's (`buildDirectoryIndexes`), and the frontmatter
 * derivation IS `buildOkfFrontmatter`. What the exporter produces at the
 * boundary and what sits at rest therefore agree on SHAPE.
 *
 * They diverge on exactly one point, deliberately: `description` synthesis.
 * The exporter falls back to the body's first sentence when frontmatter has
 * no `description`, because Google's reference implementation refuses
 * documents without one. At rest that fallback would write a sentence nobody
 * authored into the vault, where nothing marks it as machine-invented — so
 * projections pass `synthesizeDescription: false`, leave the entry bare (§6
 * allows `* [Title](file.md)`), and REPORT the gap via `missingDescription`
 * so it can be fixed at the source instead of papered over.
 *
 * Every generated file carries a MARKER line (a blockquote — the one body
 * construct the conformance checker tolerates anywhere, so marked files still
 * lint clean as OKF). The marker is how the rest of the toolchain recognises
 * a projection: the graph builder and llms.txt exporter exclude marked files
 * from content, the refresh planner refuses to overwrite an UNmarked
 * homonym (a hand-written `index.md` is someone's content, not ours to
 * clobber), and stale marked indexes (their directory emptied) are deleted.
 *
 * Pure module: no I/O, no clock — callers inject `now` (tests pin bytes).
 */

import {
  OKF_VERSION,
  buildOkfFrontmatter,
  buildDirectoryIndexes,
  newestDateString,
} from './okf-bundle-exporter.mjs';

/** Detection prefix — STABLE. Changing it orphans every deployed projection. */
export const PROJECTION_MARKER = 'Generated by obsidian-mcp-router';

/** The full marker line (blockquote → tolerated by the conformance checker). */
export function projectionMarkerLine() {
  return (
    `> ${PROJECTION_MARKER} — index de navigation généré (projection OKF §6/§7). ` +
    'Ne pas éditer à la main, ne pas wikilinker · generated navigation file — do not ' +
    'edit by hand, do not wikilink. Refresh: `refresh_okf_projections`.'
  );
}

/**
 * Is this vault-relative path one of the RESERVED projection paths?
 * Exact lowercase basenames only — `Index.md` is somebody's content page.
 */
export function isProjectionPath(relPath) {
  const p = String(relPath ?? '').replace(/\\/g, '/').replace(/^\.\//, '');
  return p === 'wiki/log.md' || /^wiki\/(?:.+\/)?index\.md$/.test(p);
}

/** Does this content carry the projection marker (scanned in the head)? */
export function hasProjectionMarker(content) {
  if (typeof content !== 'string' || !content) return false;
  // Head-scan: the marker sits right after the (optional) frontmatter +
  // heading. 20 lines is generous; scanning the whole file would let a page
  // QUOTING the marker be mistaken for a projection.
  return content.split(/\r?\n/, 20).some((l) => l.startsWith(`> ${PROJECTION_MARKER}`));
}

/** A page is wiki CONTENT when it is under wiki/ and not a projection. */
export function isWikiContentPath(relPath) {
  const p = String(relPath ?? '').replace(/\\/g, '/').replace(/^\.\//, '');
  return /^wiki\/.+\.md$/i.test(p) && !isProjectionPath(p);
}

/** Insert the marker line into a generated index/log body. */
function withMarker(content) {
  const lines = content.split('\n');
  // Root index opens with a frontmatter block; skip past it, then past the
  // `# Heading` + its blank line, so the marker reads as the file's byline.
  let i = 0;
  if (lines[0] === '---') {
    i = lines.indexOf('---', 1) + 1;
    while (lines[i] === '') i += 1;
  }
  if (/^# /.test(lines[i] ?? '')) {
    i += 1;
    while (lines[i] === '') i += 1;
  }
  lines.splice(i, 0, projectionMarkerLine(), '');
  return lines.join('\n');
}

/**
 * Build ALL projection files for a wiki tree.
 *
 * @param {object} input
 * @param {Array<{path: string, frontmatter: Record<string, any>, body: string}>} input.pages
 *   Every CONTENT page under `wiki/` (vault-relative paths, posix). Projection
 *   paths are filtered out defensively.
 * @param {string} input.vaultName Display name for the root index heading.
 * @param {string} input.now Injected ISO date/datetime (fallback timestamp).
 * @returns {{files: Array<{path: string, content: string}>}}
 *   Projection files with VAULT-relative paths (`wiki/...`), LF endings.
 */
export function buildProjections({ pages, vaultName, now }) {
  const documents = [];
  const missingDescription = [];
  for (const page of pages ?? []) {
    const rel = String(page.path).replace(/\\/g, '/');
    if (!isWikiContentPath(rel)) continue;
    const inWiki = rel.replace(/^wiki\//, '');
    const basename = inWiki.split('/').pop().replace(/\.md$/i, '');
    // Same derivation as the export bundle, with ONE deliberate divergence:
    // `synthesizeDescription: false`. The exporter falls back to the body's
    // first sentence because Google's tooling refuses description-less
    // documents; at rest that would plant a sentence nobody wrote into the
    // vault, where nothing distinguishes it from an authored one. Missing
    // descriptions are reported to the caller instead — the entry degrades to
    // the bare `* [Title](file.md)` form, which §6 allows.
    const pageWarnings = [];
    const okfFrontmatter = buildOkfFrontmatter(
      page.frontmatter ?? {}, page.body ?? '', basename, now, pageWarnings,
      { synthesizeDescription: false },
    );
    if (pageWarnings.some((w) => w.includes('no `description`'))) missingDescription.push(rel);
    documents.push({ newPath: inWiki, okfFrontmatter, frontmatter: page.frontmatter ?? {} });
  }

  // §6 indexes — the exporter's own builder, marker injected per file. The
  // root index's `> summary` slot carries the marker directly.
  const indexFiles = buildDirectoryIndexes({
    documents,
    vaultName,
    summary: null,
  }).map((f) => ({
    path: `wiki/${f.path}`,
    content: `${withMarker(f.content).trimEnd()}\n`,
  }));

  // §7 log — newest-first, derived from frontmatter dates only. Pages whose
  // frontmatter carries no parseable date land under a final non-date heading
  // (tolerated by the checker) instead of inheriting `now`, which would make
  // the same tree produce a different log tomorrow.
  const dated = new Map(); // 'YYYY-MM-DD' → [doc]
  const undated = [];
  for (const doc of documents) {
    const newest = newestDateString(doc.frontmatter);
    if (newest) {
      const day = newest.slice(0, 10);
      if (!dated.has(day)) dated.set(day, []);
      dated.get(day).push(doc);
    } else {
      undated.push(doc);
    }
  }
  const logLines = ['# Update Log', '', projectionMarkerLine(), ''];
  const days = [...dated.keys()].sort().reverse();
  // Same title sanitation as `indexEntryLine` (review v0.59.0 F2): the title
  // sits inside a markdown link in a generated file — brackets would hijack
  // the link target, newlines would break the §7 line grammar.
  const safeTitle = (t) => String(t ?? '')
    .replace(/\s+/g, ' ')
    .replace(/\[/g, '(')
    .replace(/\]/g, ')')
    .trim();
  const entryLine = (doc) => {
    const created = typeof doc.frontmatter.created === 'string'
      ? doc.frontmatter.created.slice(0, 10) : null;
    const day = (newestDateString(doc.frontmatter) ?? '').slice(0, 10);
    const verb = created && created === day ? 'Created' : 'Updated';
    return `* **${verb}**: [${safeTitle(doc.okfFrontmatter.title)}](${doc.newPath})`;
  };
  for (const day of days) {
    logLines.push(`## ${day}`, '');
    const docs = dated.get(day).slice().sort((a, b) => a.newPath.localeCompare(b.newPath));
    for (const doc of docs) logLines.push(entryLine(doc));
    logLines.push('');
  }
  if (undated.length > 0) {
    logLines.push('## Undated', '');
    for (const doc of undated.slice().sort((a, b) => a.newPath.localeCompare(b.newPath))) {
      logLines.push(`* [${safeTitle(doc.okfFrontmatter.title)}](${doc.newPath})`);
    }
    logLines.push('');
  }
  const logFile = { path: 'wiki/log.md', content: `${logLines.join('\n').trimEnd()}\n` };

  const files = [...indexFiles, logFile].sort((a, b) => a.path.localeCompare(b.path));
  // Sorted, not in page order: the whole return value is compared for
  // byte-determinism, so an input-order-dependent array would make the same
  // tree produce a different result depending on how the walker enumerated it.
  return { files, missingDescription: missingDescription.sort() };
}

/**
 * Diff generated projections against what is currently on disk/vault.
 *
 * @param {object} input
 * @param {Array<{path: string, content: string}>} input.generated From buildProjections
 * @param {Map<string, string|null>} input.current Every EXISTING file at a
 *   projection path → its content. Callers include existing `index.md`/`log.md`
 *   files that the generator did NOT produce (stale ones), so deletions are
 *   planned too.
 * @returns {{
 *   writes: Array<{path: string, content: string}>,     // new or changed
 *   unchanged: string[],
 *   deletes: string[],       // marked projections whose directory is gone
 *   conflicts: string[],     // an UNMARKED file squats a projection path
 * }}
 */
export function planProjectionWrites({ generated, current }) {
  const writes = [];
  const unchanged = [];
  const conflicts = [];
  const generatedPaths = new Set(generated.map((f) => f.path));

  for (const file of generated) {
    const existing = current.get(file.path);
    if (existing === undefined || existing === null) {
      writes.push(file);
    } else if (!hasProjectionMarker(existing) && existing.trim() !== '') {
      // Somebody's hand-written page holds this name. Never ours to clobber —
      // report and leave it. (The v0.58.0 rename freed the basenames, so this
      // only happens when a human deliberately re-created one.)
      conflicts.push(file.path);
    } else if (existing === file.content) {
      unchanged.push(file.path);
    } else {
      writes.push(file);
    }
  }

  const deletes = [];
  for (const [path, content] of current) {
    if (generatedPaths.has(path)) continue;
    if (!isProjectionPath(path)) continue;
    // Only files WE generated are ours to remove; an unmarked stray stays.
    if (hasProjectionMarker(content ?? '')) deletes.push(path);
  }
  deletes.sort();

  return { writes, unchanged, deletes, conflicts };
}
